<script setup lang="ts">import{ref,computed}from'vue';import{MAX_YEAR,MIN_YEAR,type OptionAnalysis}from'../../core/models';import{isAnchor}from'../../core/timeline';const props=defineProps<{options:OptionAnalysis[]}>();const hidden=ref(new Set<string>());const colors=['#4f5db7','#d58a32','#8b5f88','#3b8667'];const x=(h:number)=>55+(h-MIN_YEAR)/(MAX_YEAR-MIN_YEAR)*405;const y=(score:number)=>230-score*1.75;const path=(o:OptionAnalysis)=>o.points.map((p,i)=>`${i?'L':'M'} ${x(p.horizon)} ${y(p.score)}`).join(' ');function toggle(id:string){const next=new Set(hidden.value);next.has(id)?next.delete(id):next.add(id);hidden.value=next}const visible=computed(()=>props.options.filter(o=>!hidden.value.has(o.option.id)));const years=computed(()=>[...new Set(props.options.flatMap(o=>o.points.map(p=>p.horizon)))].sort((a,b)=>a-b));const hasObservation=computed(()=>props.options.some(o=>o.points.some(p=>p.kind==='observation')))</script>
<template><div class="curve-card"><div class="curve-head"><div><span>REGRET OVER TIME</span><h3>后悔曲线</h3></div><div class="legend"><button v-for="(o,i) in options" :key="o.option.id" :class="{off:hidden.has(o.option.id)}" @click="toggle(o.option.id)"><i :style="{background:colors[i]}"></i>{{o.option.name}}</button></div></div><svg viewBox="0 0 500 280" role="img" aria-label="各选项未来十年的后悔指数曲线"><g class="grid"><line v-for="v in [0,25,50,75,100]" :key="v" x1="55" x2="460" :y1="y(v)" :y2="y(v)"/><text v-for="v in [0,25,50,75,100]" :key="`t${v}`" x="22" :y="y(v)+4">{{v}}</text></g><g v-for="o in visible" :key="o.option.id"><path :d="path(o)" fill="none" :stroke="colors[options.indexOf(o)]" stroke-width="4"/><circle v-for="p in o.points" :key="p.horizon" :cx="x(p.horizon)" :cy="y(p.score)" :r="p.kind==='observation'?5:6" :fill="p.kind==='observation'?'#f8f6ef':colors[options.indexOf(o)]" :stroke="colors[options.indexOf(o)]" :stroke-width="p.kind==='observation'?2.5:0"><title>{{o.option.name}} · {{p.horizon}}年：{{p.score}}{{p.kind==='observation'?'（观察年·规则推算）':'（锚点）'}}</title></circle></g><text v-for="h in years" :key="h" :x="x(h)" y="268" text-anchor="middle" :class="{obs:!isAnchor(h)}">{{h}} 年</text></svg><p v-if="hasObservation" class="curve-note">空心点为观察年份，由 1 / 5 / 10 年锚点规则分段线性推算，不参与总分，也不是对未来的预测。</p></div></template>
